/* ============ A) GUARDARRAIL (con contexto de conversacion) ============
   Filtra antes de gastar tokens: inyeccion, temas ajenos y mensajes vacios.
   El nodo Memoria corre ANTES que este, asi que aqui ya llega el resumen
   de la conversacion (ctx): una respuesta corta como "si, guiame" ya NO se
   bloquea si hay una conversacion de la tienda en curso. */
const wh = $('Webhook').first().json;
const body = wh.body || wh;
const lang = body.lang === 'en' ? 'en' : 'es';
const raw = String(body.mensaje || '');
const t = raw.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const ctx = String($input.first().json.ctx || '').trim();

const INYECCION = [
  'ignora', 'ignore previous', 'olvida tus instrucciones', 'olvida lo anterior',
  'dame tu prompt', 'tu prompt', 'system prompt', 'instrucciones del sistema',
  'reveal your', 'act as', 'actua como si fueras', 'jailbreak', 'dan mode',
  'developer mode', 'sin filtro', 'sin restricciones', 'prompt original'
];

const TEMA = [
  /* saludos y despidas: NO deben bloquearse, son el primer mensaje tipico */
  'hola', 'holis', 'hey', 'hi', 'hello', 'buenas', 'saludos', 'que tal', 'que onda', 'que mas', 'buenos dias', 'buenas tardes', 'buenas noches', 'todo bien', 'que cuentas', 'como estas', 'como andas', 'que haces', 'bienvenido', 'welcome', 'how are you', 'how are u', 'how r u', 'whats up', 'good morning', 'good afternoon', 'good evening', 'hi there', 'hey there', 'greetings', 'gracias', 'thanks', 'thank you', 'adios', 'bye', 'chao', 'nos vemos', 'hasta luego',
  'product', 'juego', 'game', 'precio', 'costo', 'cuanto', 'stock', 'disponib',
  'agotad', 'catalog', 'tienda', 'carrito', 'cart', 'checkout', 'pedido', 'order',
  'moneda', 'currency', 'envio', 'shipping', 'delivery', 'devolucion',
  'refund', 'garantia', 'pago', 'pay', 'tarjeta', 'paypal', 'transferencia',
  'cuenta', 'login', 'sesion', 'registro', 'password', 'perfil', 'dato', 'privacidad',
  'nivel', 'xp', 'experiencia', 'punto', 'vip', 'ayuda', 'help', 'pregunta',
  'tell me', 'dime', 'recomienda', 'recomiendame', 'opinion', 'mejores', 'worth it',
  'disponible', 'existe', 'venden', 'tienen', 'hay', 'venta', 'buy', 'comprar'
];

/* Respuestas cortas de seguimiento: por si solas no nombran la tienda,
   pero responden a algo que SI se estaba hablando (el bot pregunto). */
const SIGUE = [
  'si', 's', 'no', 'dale', 'bueno', 'ok', 'obvio', 'claro', 'exacto',
  'guiame', 'guiar', 'cuentame', 'dime', 'a ver', 'por supuesto',
  'el primero', 'el segundo', 'el tercero', 'el de', 'ese', 'esa', 'este',
  'esta', 'otro', 'otra', 'nada', 'siguiente', 'repetir', 'empeza',
  'empezamos', 'vamos', 'va', 'listo', 'entendido', 'suena bien',
  'me interesa', 'no me interesa', 'dale pues', 'pues', 'bien'
];

/* Temas claramente ajenos: se bloquean aunque el mensaje sea corto
   y aunque haya conversacion en curso. */
const FUERA = [
  'politica', 'presidente', 'eleccion', 'gobierno', 'religion', 'iglesia',
  'futbol', 'seleccion', 'mundial', 'liga', 'guerra', 'droga', 'arma',
  'sexo', 'porn', 'muerte', 'suicidio', 'racis', 'nazi', 'hackear',
  'virus', 'python', 'javascript', 'programar', 'tarea', 'examen',
  'escuela', 'universidad', 'matematicas', 'cancion', 'musica', 'pelicula',
  'anime', 'novia', 'novio', 'amor', 'horoscopo', 'chiste', 'gossip'
];

const tokens = t.split(/[^a-z0-9]+/).filter(Boolean);
const sigue = SIGUE.some((k) => tokens.includes(k) || (k.length > 4 && t.includes(k)));
const corto = t.length <= 25;

const MENSAJE_BLOQUEO = lang === 'en'
  ? 'I am the PixelVault assistant, so I can only talk about the store: products and stock, cart, currencies, shipping, returns, payments and your account. How can I help with that?'
  : 'Soy el asistente de PixelVault, asi que solo puedo hablar de la tienda: productos y stock, carrito, monedas, envios, devoluciones, pagos y tu cuenta. En que te ayudo?';

let reply = '';
let motivo = '';

const injection = INYECCION.find((k) => t.includes(k));
if (injection) {
  motivo = 'inyeccion';
  reply = lang === 'en'
    ? 'I can only help with PixelVault: products, cart, currencies, shipping, payments and your account. What can I look up for you?'
    : 'Solo puedo ayudarte con cosas de PixelVault: productos, carrito, monedas, envios, pagos y tu cuenta. Que te busco?';
} else if (!t || t.length < 2) {
  motivo = 'vacio';
  reply = lang === 'en' ? 'Could you write your question again?' : 'Me puedes escribir la pregunta otra vez?';
} else if (TEMA.some((k) => t.includes(k))) {
  /* Tema de la tienda: pasa a la IA con la memoria. */
} else if (FUERA.some((k) => t.includes(k))) {
  motivo = 'fuera_de_temario';
  reply = MENSAJE_BLOQUEO;
} else if (sigue) {
  /* Respuesta corta de seguimiento: pasa a la IA con el contexto. */
} else if (ctx && corto) {
  /* Mensaje muy corto con conversacion en curso: la IA decide con contexto. */
} else {
  motivo = 'fuera_de_temario';
  reply = MENSAJE_BLOQUEO;
}

return [{ json: {
  ok: motivo === '',
  motivo,
  sesion: body.sesion || '',
  usuario: body.usuario || null,
  lang,
  mensaje: raw.slice(0, 500),
  ctx,
  reply
} }];

const body = $('Webhook').first().json.body || $('Webhook').first().json;
const lang = body.lang === 'en' ? 'en' : 'es';
const ctx = String($input.first().json.ctx || '').trim();

const CATALOGO = (body.catalogo || [])
  .map((p) => `- ${p.nombre} | ${p.categoria} | USD ${p.precio} | stock: ${p.cantidad}`)
  .join('\n') || '(sin datos de catalogo)';

const ES = `Eres Vault-Bot, el asistente virtual de PixelVault, una tienda de videojuegos, merchandising, accesorios y coleccionables.

Reglas de la tienda:
- Productos y stock reales. El catalogo vigente va abajo; si algo no esta, di que no tienes ese dato. Nunca inventes precios.
- Monedas: 17 disponibles, los precios se guardan en USD y se muestran en la moneda del cliente.
- Envios a toda Latinoamerica y Espana: 3 a 7 dias habiles.
- Devoluciones: 30 dias en productos sellados.
- Pagos: Visa, Mastercard, PayPal y transferencia bancaria.
- Registro e inicio de sesion obligatorio para comprar. Contrasenas con hash, nunca en texto plano.
- Cada compra da XP igual al total en dolares y sube de nivel.
- Clasificacion de datos en 4 niveles: publicos, semi-privados, privados y sensibles.
- Si no sabes algo de la tienda, dilo con honestidad en vez de inventar.
- Si te preguntan algo ajeno a la tienda, responde en 1 sola frase redirigiendo a PixelVault (productos, stock, carrito, monedas, envios, pagos y cuenta).\n
Formato: maximo 3 frases cortas, tono cercano de gamer, sin markdown, usa \n entre ideas y termina con una pregunta de seguimiento.`;

const EN = `You are Vault-Bot, the virtual assistant of PixelVault, a store for video games, merchandising, accessories and collectibles.

Store rules:
- Real products and real stock. The current catalog is listed below; if something is not there, say you do not have that data. Never invent prices.
- 17 currencies available, prices are stored in USD and shown in the customer currency.
- Shipping to all Latin America and Spain: 3 to 7 business days.
- Returns: 30 days on sealed products.
- Payments: Visa, Mastercard, PayPal and bank transfer.
- Registration and login are required to buy. Passwords are hashed, never plain text.
- Every purchase gives XP equal to the dollar total and raises the level.
- Data is classified in 4 levels: public, semi-private, private and sensitive.
- If you do not know something about the store, say so honestly instead of making it up.
- If asked something unrelated to the store, reply in one single sentence redirecting to PixelVault topics (products, stock, cart, currencies, shipping, payments, account).\n
Format: maximum 3 short sentences, friendly gamer tone, no markdown, use \n between ideas and end with a follow-up question.`;

const quien = body.usuario ? `${body.usuario} (${body.rol}, moneda ${body.moneda})` : 'visitante sin cuenta';

const messages = [
  { role: 'system', content: `${lang === 'en' ? EN : ES}\n\nCatalogo actual:\n${CATALOGO}` },
  { role: 'system', content: `Contexto del cliente: ${quien}` }
];

/* Memoria de la conversacion, leida de chat_log por el nodo anterior. */
if (ctx) {
  messages.push({ role: 'system', content: `Resumen de lo que ya se hablo (no lo repitas):\n${ctx}` });
}

messages.push({ role: 'user', content: String(body.mensaje || '').slice(0, 500) });

const contents = messages
  .filter((m) => m.role !== 'system')
  .map((m) => ({ role: m.role === 'assistant' ? 'model' : 'user', parts: [{ text: m.content }] }));
const systemText = messages.filter((m) => m.role === 'system').map((m) => m.content).join('\n\n');

return [{ json: {
  model: 'gemini-3.5-flash-lite',
  temperature: 0.4,
  max_tokens: 1024,
  body: {
    systemInstruction: { parts: [{ text: systemText }] },
    contents,
    generationConfig: { temperature: 0.4, maxOutputTokens: 1024 }
  },
  meta: { sesion: body.sesion || '', usuario: body.usuario || null, lang }
} }];

/* ============ B) VALIDACION + RESPALDO ============
   Normaliza la salida: si la IA no devolvio nada utilizable,
   responde con un mensaje de respaldo en vez de cortar el flujo. */
const data = $input.first().json;
const entrada = $('Guardarrail').first().json;
const mensaje = String(entrada.mensaje || '').slice(0, 500);

/* Si ya viene del guardarrail, pasa derecho. */
if (typeof data.reply === 'string' && data.reply.trim()) {
  return [{ json: {
    reply: data.reply.slice(0, 900),
    fuente: 'guardarrail',
    motivo: data.motivo || '',
    sesion: data.sesion || '',
    usuario: data.usuario || null,
    lang: data.lang || 'es',
    mensaje,
    ok: false
  } }];
}

const meta = $('Prompt').first().json.meta || {};
const lang = meta.lang === 'en' ? 'en' : 'es';

let reply = data?.candidates?.[0]?.content?.parts
  ? data.candidates[0].content.parts.map((p) => p.text || '').join('').trim()
  : '';

reply = String(reply).trim().slice(0, 900);
let fuente = 'n8n';

if (!reply) {
  /* Respaldo: la IA no esta disponible, pero el chat sigue vivo. */
  fuente = 'respaldo';
  reply = lang === 'en'
    ? 'I could not reach the assistant right now. I can still help you look up products, prices, stock, shipping, currencies and payments.'
    : 'No pude conectar con el asistente en este momento. Aun asi puedo ayudarte con productos, precios, stock, envios, monedas y pagos.';
}

return [{ json: {
  reply,
  fuente,
  sesion: meta.sesion || entrada.sesion || '',
  usuario: meta.usuario || entrada.usuario || null,
  lang,
  mensaje,
  ok: true,
  modelo: data?.model || 'gemini-3.5-flash-lite'
} }];
